-- ---------- Stories 13 to 16 ----------
INSERT INTO listening_story (created_at, updated_at, title, script, level, difficulty)
SELECT now(), now(), v.title, v.script, 3, 'HARD'
FROM (VALUES
    ('Northgate Bank: The Account That Could Not Sign In',
     'Northgate Bank ran Outlook to Outlook for eighteen hundred mailboxes and Slack to Teams for the same staff, both inside a security regime that had to approve every step. Migration manager Priyanka Menon had cleared a forty-question review before either began. The incident arrived anyway, and it arrived twice in the same shape. On the Mail side, the migration service account was blocked overnight by a conditional access policy that requires multi-factor authentication from any unrecognised location, and the migration servers were an unrecognised location. Eleven hours were lost. The exemption took forty minutes to arrange and two days to approve, because the person who could approve it was on leave and the escalation path named a role rather than a deputy. Nine days later the Slack to Teams job stopped for the same reason, on a different account, because the exemption had been raised for one account rather than for the class of accounts the migration used. Priyanka did not treat the second as a repeat of the first. In the review she separated them: the first was a gap in discovery, since nobody had asked what conditional access policies applied to service accounts, and the second was a gap in remediation, since the fix had been scoped to the symptom rather than the cause. Two changes followed. Discovery now asks for conditional access policies by name, and any exemption is raised for the account class. The Message side carried a second issue that had nothing to do with security. Slack to Teams moves private channels only where the migration account is a member, and Northgate had four hundred private channels whose owners had to add that account one at a time. Two hundred and ninety did so within the week. The remaining hundred and ten were chased for a fortnight, thirty were never actioned, and those channels stayed in Slack under a read-only licence that the bank now renews annually.'),

    ('Orlow Pharma: Where the Reports Go',
     'Orlow Pharma is headquartered in Germany, and its works council required written confirmation that no employee content would leave the European region during either of its migrations: Gmail to Outlook for twelve hundred mailboxes, and OneDrive to SPO for the same users. Architect Julien Moreau confirmed both content paths were European and then checked one component further and found the exception. Migration progress reports were generated by a service hosted in North America, and those reports contain file names, folder paths and mailbox display names -- nothing that could be called content, and everything a works council would reasonably call personal data. He raised it himself, in the same meeting where he confirmed the content path, before anyone had asked. Two options went to the council. Move the reporting to a European instance, which existed but had never been used at that scale and needed three weeks of validation; or generate reports without names, which was immediate and made troubleshooting considerably harder for his own team. The council chose the first and Orlow accepted the three weeks. Validation found a defect: a character encoding fault that mangled German file names in the European reporting instance, which the vendor fixed eight months later and which the team worked around for the duration. The migrations themselves were unremarkable except for one asymmetry worth noting. On the Mail side, a mailbox is a single object with one owner, so residency is simple. On the Content side, a document in a shared library has an owner, an editor list and a link that may have been sent anywhere, and the works council question about where content lives is genuinely harder to answer for the second than the first. Julien recommendation, accepted in principle and still not implemented, was that the standard architecture diagram show data paths rather than only content paths, because the report about the migration turned out to be the part that left the region.'),

    ('Pinehurst Council: Public by Default',
     'Pinehurst Council migrated Teams to Teams between two authorities that had merged, and Shared Drive to SPO for the same combined workforce of two thousand. Both migrations sat under freedom-of-information obligations: any resident may request a document or a recorded communication, and the authority must find it. Programme lead Elena Duarte ran the two on one plan and one risk register, which she later described as the single decision that made the project possible. The Content side raised the harder question. The two authorities had used Shared Drives with opposite conventions -- one filed by service area and one by year -- and merging them into SPO meant choosing. Elena refused to let the migration team choose. She had the records manager produce a target structure, signed, before the first wave, and the migration mapped into it. That took six weeks that the plan had not contained, and it is the reason a resident request can now be answered in one search rather than two. The Message side had a subtler problem. Teams to Teams preserves channel conversations, but the two authorities had different retention settings, one deleting chat after eighteen months and the other keeping everything. Merging tenants means one setting wins. Keeping everything is safer for freedom of information and more expensive; deleting after eighteen months is cheaper and creates a gap a requester can notice. The council chose to keep everything, and to backfill the deleted period from the archive of the authority that had it, which was possible for eleven of the eighteen months. Elena wrote the seven-month gap into the register as a known limitation with a published explanation, rather than leaving it to be discovered. In the closure meeting she noted that both decisions -- the filing structure and the retention setting -- had been taken by people whose job is records rather than technology, and that this was the point.'),

    ('Quarry Analytics: The Cost of Keeping Both',
     'Quarry Analytics had grown from forty people to four hundred through two acquisitions, and it was paying for it. Slack to Slack consolidated three workspaces into one, and SPO to OneDrive moved eleven hundred personal work areas out of a departmental site structure that had become a filing cabinet. Finance director Marianne Foss had a target rather than a deadline: reduce annual platform spend by a hundred and forty thousand dollars. That framing changed how the project was run. Every technical decision was priced. Keeping the two source Slack workspaces alive for thirty days after cutover, which the team recommends, cost eleven thousand dollars a month, so Marianne asked what the thirty days actually buys. Migration lead Ade Bakare answered honestly: across eleven previous projects, the average interval between cutover and the last genuine recovery request was nineteen days, but about two thirds of those requests could have been served from the destination by someone who simply could not find the content. That answer weakened his own recommendation and he gave it anyway. Marianne then proposed something better than either position: decommission at ten days, and before that, export the twelve highest-risk channels and the eight largest personal areas to cold storage for three months at nine hundred dollars. Ade agreed and added one condition of his own, that the export be verified by restoring three items at random before anything was switched off. The verification found one export that had completed incompletely, which was re-run. In the ten weeks that followed there were four recovery requests. Three were served from the destination, where the content had been all along. The fourth came from the cold export and concerned a channel that had not been in the original twelve; it had been added because the engineer running the export rounded up to fourteen on his own initiative. The programme came in at a hundred and fifty-two thousand dollars of annual saving, and Ade recorded the fourteenth channel specifically, because the process would not have covered it and a person did.')
    ) AS v(title, script)
WHERE NOT EXISTS (SELECT 1 FROM seed_state WHERE seed_key = 'l3-listening-bank-v3');

